  1	import { test } from 'node:test';
  2	import assert from 'node:assert/strict';
  3	import * as fs from 'node:fs';
  4	import * as os from 'os';
  5	import * as path from 'node:path';
  6	import { loadConfig, saveConfigField } from '../config/config.js';
  7	import { createTempDirTracker } from './test-helpers.js';
  8	
  9	const makeTempDir = createTempDirTracker('paralizer-config-test-');
 10	
 11	function writeConfig(dir: string, data: Record<string, unknown>): string {
 12	    const configPath = path.join(dir, 'config.json');
 13	    fs.writeFileSync(configPath, JSON.stringify(data, null, 4) + '\n', 'utf8');
 14	    return configPath;
 15	}
 16	
 17	// --- Happy path ---
 18	
 19	test('loadConfig() loads a minimal valid config with defaults applied', () => {
 20	    const dir = makeTempDir();
 21	    const configPath = writeConfig(dir, {
 22	        projectsFolder: '/tmp/projects',
 23	        storageFolder: '/tmp/storage',
 24	    });
 25	    const config = loadConfig(configPath);
 26	    assert.strictEqual(config.projectsFolder, '/tmp/projects');
 27	    assert.strictEqual(config.storageFolder, '/tmp/storage');
 28	    assert.strictEqual(config.cloneDepth, 50);
 29	    assert.strictEqual(config.serverPort, 4200);
 30	    assert.strictEqual(config.gitPollingIntervalSeconds, 30);
 31	});
 32	
 33	test('loadConfig() respects explicit optional values', () => {
 34	    const dir = makeTempDir();
 35	    const configPath = writeConfig(dir, {
 36	        projectsFolder: '/tmp/projects',
 37	        storageFolder: '/tmp/storage',
 38	        cloneDepth: 10,
 39	        serverPort: 8080,
 40	        gitPollingIntervalSeconds: 60,
 41	    });
 42	    const config = loadConfig(configPath);
 43	    assert.strictEqual(config.cloneDepth, 10);
 44	    assert.strictEqual(config.serverPort, 8080);
 45	    assert.strictEqual(config.gitPollingIntervalSeconds, 60);
 46	});
 47	
 48	// --- Missing-file errors ---
 49	
 50	test('loadConfig() throws when config.json does not exist', () => {
 51	    assert.throws(
 52	        () => loadConfig('/nonexistent/path/config.json'),
 53	        /config\.json not found/
 54	    );
 55	});
 56	
 57	test('missing-config error message mentions config.dist.json', () => {
 58	    let msg = '';
 59	    try {
 60	        loadConfig('/nonexistent/path/config.json');
 61	    } catch (err) {
 62	        msg = (err as Error).message;
 63	    }
 64	    assert.ok(msg.includes('config.dist.json'), 'error should reference config.dist.json');
 65	});
 66	
