 97	});
 98	
 99	test('loadConfig() throws when projectsFolder is null', () => {
100	    const dir = makeTempDir();

100	
101	/**
102	 * Parses a numeric config field, enforcing integer-only values and optional
103	 * `[min, max]` range bounds.
104	 *
105	 * - If `value` is not a `number`, returns `defaultValue`.
106	 * - If `value` is a number but not a safe integer (e.g. a float like `220.5`),
107	 *   returns `defaultValue`.
108	 * - If `min` and `max` are provided and the integer value is outside that range,
109	 *   emits `console.warn` but returns the value as-is (no clamping).
110	 *
111	 * @param value     Raw value read from the config file.
112	 * @param fieldName Field name used in warning messages.
113	 * @param defaultValue Fallback value for non-numeric or float inputs.
114	 * @param min       Optional lower bound (inclusive).
115	 * @param max       Optional upper bound (inclusive).
116	 */
117	function parseIntegerField(
118	    value: unknown,
119	    fieldName: string,
120	    defaultValue: number,
121	    min?: number,
122	    max?: number,
123	): number {
124	    if (typeof value !== 'number') {
125	        return defaultValue;
126	    }
127	    if (!Number.isInteger(value)) {
128	        return defaultValue;
129	    }
130	    if (min !== undefined && max !== undefined && (value < min || value > max)) {
131	        console.warn(
132	            `Configuration warning: "${fieldName}" value ${value} is outside the allowed range ` +
133	            `[${min}, ${max}]. The value will be used as-is.`
134	        );
135	    }
136	    return value;
137	}
138	
139	/**
140	 * Validates and returns the `gitCredentials` value from the raw config.
141	 *
142	 * @returns undefined when the field is absent or null.
143	 * @throws {Error} If the value is present but is not a plain object, or if any
144	 *   key maps to a non-string or empty-string token.
145	 */
146	function parseGitCredentials(value: unknown): Record<string, string> | undefined {
147	    if (value === undefined || value === null) {
148	        return undefined;
149	    }
150	
151	    if (typeof value !== 'object' || Array.isArray(value)) {
152	        throw new Error(
153	            'Configuration error: "gitCredentials" must be a plain object mapping hostnames to credential strings.'
154	        );
155	    }
156	
157	    const credentials = value as Record<string, unknown>;
158	
159	    for (const [key, token] of Object.entries(credentials)) {
160	        if (typeof token !== 'string') {
161	            throw new Error(
162	                `Configuration error: gitCredentials["${key}"] must be a string, got ${typeof token}.`
163	            );
164	        }
165	        if (token === '') {
166	            throw new Error(
167	                `Configuration error: gitCredentials["${key}"] must not be an empty string.`
168	            );
169	        }
170	    }
171	
172	    return credentials as Record<string, string>;
173	}
174	
175	/**
176	 * Reads `config.json`, sets or removes a single top-level field, and writes the
177	 * file back via `writeJsonFile()`. All other fields — including `_instructions`
178	 * — are preserved.
179	 *
180	 * @param field - The top-level key to modify (e.g. `"gitCredentials"`).
181	 * @param value - The value to set, or `undefined` to remove the field.
182	 * @param configPath - Optional absolute path to the config file. Defaults to
183	 *   the tool-root `config.json`.
184	 * @throws {Error} If `config.json` cannot be read or written.
185	 */
186	export function saveConfigField(
187	    field: string,
188	    value: unknown,
189	    configPath?: string,
190	): void {
191	    const resolvedConfigPath = configPath ?? getConfigPath();
192	    const raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
193	
194	    if (value === undefined) {
195	        delete raw[field];
196	    } else {
197	        raw[field] = value;
198	    }
199	
200	    writeJsonFile(resolvedConfigPath, raw);
201	
202	    // config.json may contain plaintext PATs in gitCredentials — restrict
203	    // file permissions to owner-only on POSIX systems.
204	    if (process.platform !== 'win32') {
205	        chmodSync(resolvedConfigPath, 0o600);
206	    }
207	}

100	    const dir = makeTempDir();
101	    const configPath = writeConfig(dir, {
102	        projectsFolder: null,
103	        storageFolder: '/tmp/storage',
104	    });
105	    assert.throws(() => loadConfig(configPath), /projectsFolder/);
106	});
107	
108	// --- gitCredentials ---
109	
110	test('loadConfig() returns gitCredentials: undefined when field is absent', () => {
111	    const dir = makeTempDir();
112	    const configPath = writeConfig(dir, {
113	        projectsFolder: '/tmp/projects',
114	        storageFolder: '/tmp/storage',
115	    });
116	    const config = loadConfig(configPath);
117	    assert.strictEqual(config.gitCredentials, undefined);
118	});
119	
120	test('loadConfig() returns gitCredentials: undefined when field is null', () => {
121	    const dir = makeTempDir();
122	    const configPath = writeConfig(dir, {
123	        projectsFolder: '/tmp/projects',
124	        storageFolder: '/tmp/storage',
125	        gitCredentials: null,
126	    });
127	    const config = loadConfig(configPath);
128	    assert.strictEqual(config.gitCredentials, undefined);
129	});
130	
131	test('loadConfig() returns parsed gitCredentials when valid entries are present', () => {
132	    const dir = makeTempDir();
133	    const configPath = writeConfig(dir, {
134	        projectsFolder: '/tmp/projects',
135	        storageFolder: '/tmp/storage',
136	        gitCredentials: { 'github.com': 'ghp_token123', 'gitlab.com': 'glpat_abc' },
137	    });
138	    const config = loadConfig(configPath);
139	    assert.deepStrictEqual(config.gitCredentials, {
140	        'github.com': 'ghp_token123',
141	        'gitlab.com': 'glpat_abc',
142	    });
143	});
144	
145	test('loadConfig() returns gitCredentials as empty object when field is {}', () => {
146	    const dir = makeTempDir();
147	    const configPath = writeConfig(dir, {
148	        projectsFolder: '/tmp/projects',
149	        storageFolder: '/tmp/storage',
150	        gitCredentials: {},
151	    });
152	    const config = loadConfig(configPath);
153	    assert.deepStrictEqual(config.gitCredentials, {});
154	});
155	
156	test('loadConfig() throws when gitCredentials is an array', () => {
157	    const dir = makeTempDir();
158	    const configPath = writeConfig(dir, {
159	        projectsFolder: '/tmp/projects',
160	        storageFolder: '/tmp/storage',
161	        gitCredentials: ['token'],
162	    });
163	    assert.throws(() => loadConfig(configPath), /gitCredentials.*plain object/);
164	});
165	
166	test('loadConfig() throws when gitCredentials is a string', () => {
167	    const dir = makeTempDir();
168	    const configPath = writeConfig(dir, {
169	        projectsFolder: '/tmp/projects',
170	        storageFolder: '/tmp/storage',
171	        gitCredentials: 'token',
172	    });
173	    assert.throws(() => loadConfig(configPath), /gitCredentials.*plain object/);
174	});
