177	    const dir = makeTempDir();
178	    const configPath = writeConfig(dir, {
179	        projectsFolder: '/tmp/projects',
180	        storageFolder: '/tmp/storage',
181	        gitCredentials: { 'github.com': 12345 },
182	    });
183	    assert.throws(() => loadConfig(configPath), /gitCredentials\["github\.com"\].*string/);
184	});
