187	    const dir = makeTempDir();
188	    const configPath = writeConfig(dir, {
189	        projectsFolder: '/tmp/projects',
190	        storageFolder: '/tmp/storage',
191	        gitCredentials: { 'github.com': '' },
192	    });
193	    assert.throws(() => loadConfig(configPath), /gitCredentials\["github\.com"\].*empty/);
194	});
