203	        storageFolder: '/tmp/storage',
204	        cloneDepth: 10,
205	    });
206	    saveConfigField('gitCredentials', { 'github.com': 'token' }, configPath);
207	    const raw = JSON.parse(fs.readFileSync(configPath, 'utf8')) as Record<string, unknown>;
208	    assert.deepStrictEqual(raw['gitCredentials'], { 'github.com': 'token' });
209	    assert.strictEqual(raw['projectsFolder'], '/tmp/projects');
210	    assert.strictEqual(raw['storageFolder'], '/tmp/storage');
211	    assert.strictEqual(raw['cloneDepth'], 10);
212	    assert.strictEqual(raw['_instructions'], 'Copy this file.');
213	});
