223	    const raw = JSON.parse(fs.readFileSync(configPath, 'utf8')) as Record<string, unknown>;
224	    assert.ok(!Object.hasOwn(raw, 'gitCredentials'), 'gitCredentials should be absent after deletion');
225	    assert.strictEqual(raw['projectsFolder'], '/tmp/projects');
226	    assert.strictEqual(raw['storageFolder'], '/tmp/storage');
